const html = $('Gmail Trigger').first().json.html

if (!html) {
  return [{ json: { error: "No HTML found" } }];
}

// Extraer todas las tablas
const tableMatches = html.match(/<table[\s\S]*?<\/table>/gi) || [];

const tables = tableMatches.map(tableHtml => {
  const rows = [];
  const rowMatches = tableHtml.match(/<tr[\s\S]*?<\/tr>/gi) || [];

  rowMatches.forEach(rowHtml => {
    const cells = [];
    const cellMatches = rowHtml.match(/<(td|th)[\s\S]*?<\/(td|th)>/gi) || [];

    cellMatches.forEach(cell => {
      const text = cell
        .replace(/<[^>]+>/g, '')
        .replace(/\s+/g, ' ')
        .trim();
      cells.push(text);
    });

    if (cells.length) rows.push(cells);
  });

  return rows;
});

return [{
  json: {
    tables,
    tablesFound: tables.length
  }
}];

// Filtra solo items con binario .xlsx o .csv y normaliza la key a "attachment"
const results = [];

for (const item of $input.all()) {
  const binaryData = item.binary || {};
  for (const key of Object.keys(binaryData)) {
    const bin = binaryData[key];
    const filename = (bin.fileName || "").toLowerCase();
    const mimeType = (bin.mimeType || "").toLowerCase();

    const isXlsx = filename.endsWith(".xlsx") && mimeType.indexOf("spreadsheetml") !== -1;
    const isCsv  = filename.endsWith(".csv")  || mimeType.indexOf("text/csv") !== -1 || mimeType.indexOf("csv") !== -1;

    if (!isXlsx && !isCsv) continue;

    results.push({
      json: item.json,
      binary: { attachment: bin }
    });
    break;
  }
}

if (results.length === 0) {
  return [{ json: { message: "No se encontraron archivos .xlsx ni .csv" } }];
}

return results;

// DEBUG — ver estructura real de tablas
const inputItems = $input.all();
const allTables = [];

inputItems.forEach((item) => {
  const tables = item.json.tables;
  if (Array.isArray(tables)) allTables.push(...tables);
});

return [{ json: { 
  tables: allTables,
  tablesFound: allTables.length,
  // Vista fácil de leer
  preview: allTables.map((table, ti) => ({
    tabla: ti,
    filas: table.map((row, ri) => ({
      fila: ri,
      celdas: row
    }))
  }))
}}];

var tables = $input.first().json.tables || [];
if (tables.length === 0) return [{ json: { error: 'Sin tablas' } }];

// ═══════════════════════════════════════════════════
// NORMALIZADOR
// ═══════════════════════════════════════════════════
function norm(s) {
  return (s || '').toString().toLowerCase().trim()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

// ═══════════════════════════════════════════════════
// SELECCIÓN INTELIGENTE DE TABLA
// Elige la tabla con más headers reconocidos
// ═══════════════════════════════════════════════════
var keyHeaders = [
  'no. serie','no serie','serie','fecha','hora','actividad','tipo de orden',
  'cliente','correo','modelo','ingeniero','nombre','email','folio','servicio'
];

var bestTable = tables[0];
var bestScore = 0;

for (var ti = 0; ti < tables.length; ti++) {
  var t = tables[ti];
  if (!t || !t[0] || t.length < 2) continue;
  var score = 0;
  for (var hi = 0; hi < t[0].length; hi++) {
    var hn = norm(t[0][hi] || '');
    for (var ki = 0; ki < keyHeaders.length; ki++) {
      if (hn.indexOf(keyHeaders[ki]) !== -1) { score++; break; }
    }
  }
  if (score > bestScore) { bestScore = score; bestTable = t; }
}

var table = bestTable;
if (table.length < 2) return [{ json: { error: 'Tabla vacia o sin datos' } }];

var rawHeaders = table[0];
var dataRows   = table.slice(1);

// ═══════════════════════════════════════════════════
// LIMPIEZA
// ═══════════════════════════════════════════════════
function clean(v) {
  if (v === null || v === undefined) return null;
  var s = String(v).trim();
  var nulls = ['', 'n/a', 'no aplica', 's/n', '.', 'na', 'ninguno', 'ninguna'];
  return nulls.indexOf(s.toLowerCase()) !== -1 ? null : s;
}

function cleanDate(v) {
  if (!v) return null;
  var s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  var p = s.split('/');
  if (p.length === 3 && p[2].length === 4) {
    return p[2] + '-' + p[1].padStart(2,'0') + '-' + p[0].padStart(2,'0');
  }
  var meses = {
    'ene':'01','enero':'01','jan':'01','feb':'02','febrero':'02',
    'mar':'03','marzo':'03','abr':'04','abril':'04','apr':'04',
    'may':'05','mayo':'05','jun':'06','junio':'06',
    'jul':'07','julio':'07','ago':'08','agosto':'08','aug':'08',
    'sep':'09','sept':'09','septiembre':'09','oct':'10','octubre':'10',
    'nov':'11','noviembre':'11','dic':'12','diciembre':'12','dec':'12'
  };
  var partes = s.toLowerCase().split(/[\s\-\/]+/);
  if (partes.length === 3 && meses[partes[1]]) {
    return partes[2].padStart(4,'0') + '-' + meses[partes[1]] + '-' + partes[0].padStart(2,'0');
  }
  return null;
}

function cleanTime(v) {
  if (!v) return null;
  var s = String(v).trim().toUpperCase();
  var hasPM = s.indexOf('PM') !== -1;
  var hasAM = s.indexOf('AM') !== -1;
  s = s.replace('AM','').replace('PM','').trim();
  var parts = s.split(':');
  if (parts.length < 2) return null;
  var h = parseInt(parts[0]);
  var min = (parts[1] || '00').slice(0,2);
  var sec = (parts[2] || '00').slice(0,2);
  if (hasPM && h !== 12) h = h + 12;
  if (hasAM && h === 12) h = 0;
  return String(h).padStart(2,'0') + ':' + min + ':' + sec;
}

// ═══════════════════════════════════════════════════
// PARSER DIRECCIÓN
// ═══════════════════════════════════════════════════
function parseDireccion(dir) {
  dir = dir || '';
  var addr_street = null, addr_extnum = null, neighborhood = null, zip_code = null;
  var iHash = dir.indexOf('#');
  if (iHash !== -1) {
    addr_street = dir.slice(0, iHash).trim();
    addr_extnum = dir.slice(iHash + 1).trim().split(/[\s,]/)[0];
  } else {
    var mNo = dir.match(/\bNum?\.?\s*(\w+)/i);
    if (mNo) {
      addr_extnum = mNo[1];
      addr_street = dir.slice(0, dir.indexOf(mNo[0])).trim();
    }
  }
  var dirUp = dir.toUpperCase();
  var colIdx = -1, colLen = 0;
  var colPats = ['COL. ','COL.','COLONIA '];
  for (var ci = 0; ci < colPats.length; ci++) {
    var idx = dirUp.indexOf(colPats[ci]);
    if (idx !== -1) { colIdx = idx; colLen = colPats[ci].length; break; }
  }
  var cpIdx = -1, cpLen = 0;
  var cpPats = ['C.P. ','C.P.','CODIGO POSTAL ','ZIP ',' CP '];
  for (var cpi = 0; cpi < cpPats.length; cpi++) {
    var idxcp = dirUp.indexOf(cpPats[cpi]);
    if (idxcp !== -1) { cpIdx = idxcp; cpLen = cpPats[cpi].length; break; }
  }
  if (colIdx !== -1 && cpIdx !== -1 && cpIdx > colIdx) {
    neighborhood = dir.slice(colIdx + colLen, cpIdx).trim();
  } else if (colIdx !== -1) {
    neighborhood = dir.slice(colIdx + colLen).split(',')[0].trim();
  }
  if (cpIdx !== -1) {
    var afterCP = dir.slice(cpIdx + cpLen).trim();
    var cpVal = afterCP.split(/[\s,]/)[0];
    if (cpVal && !isNaN(cpVal)) zip_code = cpVal;
  }
  return { addr_street: clean(addr_street), addr_extnum: clean(addr_extnum), neighborhood: clean(neighborhood), zip_code: clean(zip_code) };
}

// ═══════════════════════════════════════════════════
// RESOLVERS
// ═══════════════════════════════════════════════════
function resolveCustomer(id, cliente) {
  var prefijos = { 'PH':'BANORTE','BX':'BBVA','SN':'SANTANDER','HB':'HSBC','SC':'SCOTIABANK','BM':'BANAMEX' };
  if (id) {
    var prefix = String(id).slice(0,2).toUpperCase();
    if (prefijos[prefix]) return prefijos[prefix];
  }
  return clean(cliente) || clean(id);
}

function resolveServiceType(v) {
  var t = (v || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if (t.indexOf('SUMINISTRO') !== -1)    return 'SUMINISTRO';
  if (t.indexOf('INSTALACION') !== -1)   return 'INSTALACION';
  if (t.indexOf('TRASLADO') !== -1)      return 'TRASLADO';
  if (t.indexOf('TRANSPORTE') !== -1)    return 'TRANSPORTE';
  if (t.indexOf('RETIRO') !== -1)        return 'RETIRO';
  if (t.indexOf('BAJA') !== -1)          return 'RETIRO';
  if (t.indexOf('MANTENIMIENTO') !== -1) return 'MANTENIMIENTO';
  if (t.indexOf('CORRECTIVO') !== -1)    return 'MANTENIMIENTO';
  if (t.indexOf('ACTIVACION') !== -1)    return 'ACTIVACION';
  if (t.indexOf('ALTA') !== -1)          return 'ACTIVACION';
  if (t.indexOf('REEMPLAZO') !== -1)     return 'REEMPLAZO';
  if (t.indexOf('CAMBIO') !== -1)        return 'REEMPLAZO';
  return null;
}

function resolveStatus(v) {
  if (!v) return 'DISPONIBLE';
  var validos = ['EN SERVICIO','REMOZADO','DISPONIBLE','EN INSTALACION','ACTIVO','BASE DE METAL','BAJA'];
  var upper = String(v).toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  for (var i = 0; i < validos.length; i++) {
    if (upper.indexOf(validos[i]) !== -1) return validos[i];
  }
  return v;
}

// ═══════════════════════════════════════════════════
// MAPA DE SINÓNIMOS — campos simples
// ═══════════════════════════════════════════════════
var SIMPLE_MAP = {
  // Orden
  'cliente':'CLIENTE', 'empresa':'CLIENTE', 'banco':'CLIENTE',
  'id':'ID', 'folio':'FOLIO', 'clave':'ID',
  'tipo de orden':'SO_TYPE', 'tipo orden':'SO_TYPE', 'actividad':'SO_TYPE',
  'actividad a realizar':'SO_TYPE',
  'servicio':'SERVICIO', 'tipo de servicio':'SERVICIO',
  'fecha':'FECHA', 'fecha de cita':'FECHA', 'fecha cita':'FECHA',
  'fecha instalacion':'FECHA', 'fecha de instalacion':'FECHA', 'fecha programada':'FECHA',
  'fecha de atencion':'FECHA', 'fecha atencion':'FECHA',
  'hora':'HORA', 'hora de cita':'HORA', 'hora cita':'HORA', 'hora instalacion':'HORA',
  // Implantador
  'correo':'EMAIL', 'email':'EMAIL', 'correo electronico':'EMAIL', 'e mail':'EMAIL',
  'correo implantador':'EMAIL',
  'telefono':'TELEFONO', 'tel':'TELEFONO', 'celular':'TELEFONO',
  'nombre':'NOMBRE_IMP', 'nombre implantador':'NOMBRE_IMP', 'implantador':'NOMBRE_IMP',
  'ingeniero':'NOMBRE_IMP',
  'segundo nombre':'MIDNAME', 'segundo nombre implantador':'MIDNAME',
  'apellido':'APELLIDO', 'apellido paterno':'APELLIDO',
  'apellido materno':'APELLIDO_MAT',
  // Destino simple (sin prefijo)
  'direccion':'DIRECCION', 'domicilio':'DIRECCION',
  'calle':'CALLE', 'numero exterior':'NUM_EXT', 'num exterior':'NUM_EXT', 'no exterior':'NUM_EXT',
  'numero interior':'NUM_INT', 'no interior':'NUM_INT',
  'colonia':'COLONIA', 'col':'COLONIA',
  'ciudad':'CIUDAD', 'estado':'ESTADO',
  'municipio':'MUNICIPIO', 'delegacion':'MUNICIPIO', 'municipio delegacion':'MUNICIPIO',
  'cp':'CP', 'codigo postal':'CP', 'c p':'CP', 'zip':'CP',
  'nivel':'NIVEL', 'nivel cajero':'NIVEL', 'nivel donde se encontrara el cajero':'NIVEL',
  'ubicacion':'NOMBRE', 'nombre ubicacion':'NOMBRE', 'sucursal':'NOMBRE',
  'lugar de instalacion':'NOMBRE', 'lugar instalacion':'NOMBRE',
  // Equipo simple (sin prefijo Eq1/Eq2)
  'serie':'SERIE', 'no serie':'SERIE', 'no. serie':'SERIE',
  'numero de serie':'SERIE', 'serial':'SERIE',
  'modelo':'MODELO', 'formato':'FORMATO', 'tipo':'FORMATO', 'subtipo':'FORMATO',
  'tipo de cabina':'FORMATO',
  'base':'BASE', 'estatus':'BASE', 'estado del inventario':'BASE',
  'estatus de cierre':'BASE',
  'marca':'MARCA', 'id externo':'ID_EXTERNO',
  'monta carga o escalera':'MONTA', 'monta carga':'MONTA', 'monta':'MONTA', 'escalera':'MONTA',
  // Campos adicionales de clientes externos
  'proveedor':'CLIENTE', 'confirmacion proveedor':'CLIENTE',
  'pendiente de fabricacion':'BASE',
  // Ignorar columnas de control interno
  'mes':'_IGNORAR', 'software':'_IGNORAR',
  // Geo
  'latitud':'LATITUD', 'lat':'LATITUD', 'longitud':'LONGITUD', 'lon':'LONGITUD'
};

// ═══════════════════════════════════════════════════
// DETECTAR TIPO DE HEADER
// ═══════════════════════════════════════════════════
function classifyHeader(raw) {
  var n = norm(raw);

  var origenPrefixes = ['origen '];
  for (var oi = 0; oi < origenPrefixes.length; oi++) {
    if (n.indexOf(origenPrefixes[oi]) === 0) {
      return { type: 'origen', field: norm(n.slice(origenPrefixes[oi].length)) };
    }
  }

  var destinoPrefixes = ['destino '];
  for (var di = 0; di < destinoPrefixes.length; di++) {
    if (n.indexOf(destinoPrefixes[di]) === 0) {
      return { type: 'destino', field: norm(n.slice(destinoPrefixes[di].length)) };
    }
  }

  var eqMatch = n.match(/^eq(?:uipo)?\s*(\d+)\s+(.+)$/);
  if (eqMatch) {
    return { type: 'equipo', eqNum: parseInt(eqMatch[1]), field: eqMatch[2] };
  }

  var premisaMatch = n.match(/^premisa\s*(\d+)\s*(comentario)?$/);
  if (premisaMatch) {
    return { type: 'premisa', num: parseInt(premisaMatch[1]), isComment: !!premisaMatch[2] };
  }

  var reqMatch = n.match(/^requerimiento\s*(\d+)\s*(comentario)?$/);
  if (reqMatch) {
    return { type: 'premisa', num: parseInt(reqMatch[1]), isComment: !!reqMatch[2] };
  }

  if (SIMPLE_MAP[n]) {
    // Campos marcados para ignorar
    if (SIMPLE_MAP[n] === '_IGNORAR') return { type: 'unknown', raw: raw };
    return { type: 'simple', field: SIMPLE_MAP[n] };
  }

  return { type: 'unknown', raw: raw };
}

function mapAddressField(field) {
  var addressMap = {
    'tipo ubicacion':'loc_type', 'tipo de ubicacion':'loc_type', 'ubicacion':'loc_type',
    'id ubicacion':'ext_loc_id', 'id externo de ubicacion':'ext_loc_id',
    'nombre ubicacion':'location_name', 'nombre de ubicacion':'location_name',
    'calle':'addr_street',
    'no exterior':'addr_extnum', 'num exterior':'addr_extnum', 'numero exterior':'addr_extnum',
    'no interior':'addr_intnum', 'num interior':'addr_intnum', 'numero interior':'addr_intnum',
    'colonia':'neighborhood',
    'ciudad':'city',
    'municipio':'county', 'delegacion':'county',
    'estado':'state',
    'cp':'zip_code', 'codigo postal':'zip_code', 'c p':'zip_code'
  };
  return addressMap[field] || null;
}

function mapEquipmentField(field) {
  var eqMap = {
    'no serie':'serialNumber', 'no. serie':'serialNumber', 'serie':'serialNumber',
    'serial':'serialNumber', 'numero de serie':'serialNumber',
    'estatus':'inv_status', 'status':'inv_status', 'base':'inv_status',
    'tipo':'inv_type',
    'subtipo':'inv_subtype', 'formato':'inv_subtype',
    'marca':'inv_brand',
    'modelo':'inv_model',
    'id externo':'id_externo', 'id ext':'id_externo',
    'carga':'ext_carga',
    'nombre':'ext_nombre',
    'comentarios':'comments', 'comentario':'comments'
  };
  return eqMap[field] || null;
}

function nullAddress() {
  return { loc_type:null, ext_loc_id:null, location_name:null, addr_street:null,
           addr_extnum:null, addr_intnum:null, neighborhood:null, city:null,
           county:null, state:null, zip_code:null };
}

// ═══════════════════════════════════════════════════
// MAIN
// ═══════════════════════════════════════════════════
var classified = rawHeaders.map(function(h) { return classifyHeader(h); });
var results = [];

for (var ri = 0; ri < dataRows.length; ri++) {
  var row = dataRows[ri];

  var hasData = row.some(function(v) { return clean(v) !== null; });
  if (!hasData) continue;

  var simple   = {};
  var origen   = nullAddress();
  var destino  = nullAddress();
  var equipos  = {};
  var premisas = {};

  for (var ci = 0; ci < classified.length; ci++) {
    var clf = classified[ci];
    var val = clean(row[ci]);
    if (val === null) continue;

    if (clf.type === 'simple') {
      if (!simple[clf.field]) simple[clf.field] = val;
    } else if (clf.type === 'origen') {
      var addrKey = mapAddressField(clf.field);
      if (addrKey && !origen[addrKey]) origen[addrKey] = val;
    } else if (clf.type === 'destino') {
      var addrKeyD = mapAddressField(clf.field);
      if (addrKeyD && !destino[addrKeyD]) destino[addrKeyD] = val;
    } else if (clf.type === 'equipo') {
      var num = clf.eqNum;
      if (!equipos[num]) equipos[num] = {};
      var eqKey = mapEquipmentField(clf.field);
      if (eqKey && !equipos[num][eqKey]) equipos[num][eqKey] = val;
    } else if (clf.type === 'premisa') {
      var pnum = clf.num;
      if (!premisas[pnum]) premisas[pnum] = { requirement: null, comment: null };
      if (clf.isComment) { premisas[pnum].comment = val; }
      else               { premisas[pnum].requirement = val; }
    }
  }

  var so_type_id = resolveServiceType(simple['SO_TYPE'] || simple['SERVICIO'] || simple['ACTIVIDAD_TEXT'] || '');
  var esTraslado = so_type_id === 'TRASLADO' || so_type_id === 'TRANSPORTE';

  var destinoFinal = nullAddress();
  var tieneDestino = Object.values(destino).some(function(v) { return v !== null; });
  var tieneOrigen  = Object.values(origen).some(function(v)  { return v !== null; });

  if (tieneDestino) {
    destinoFinal = destino;
  } else {
    var dir = simple['DIRECCION'] ? parseDireccion(simple['DIRECCION']) : { addr_street:null, addr_extnum:null, neighborhood:null, zip_code:null };
    destinoFinal = {
      loc_type:      simple['NIVEL']     || null,
      ext_loc_id:    simple['ID']        || null,
      location_name: simple['NOMBRE']    || null,
      addr_street:   simple['CALLE']     || dir.addr_street,
      addr_extnum:   simple['NUM_EXT']   || dir.addr_extnum,
      addr_intnum:   simple['NUM_INT']   || null,
      neighborhood:  simple['COLONIA']   || dir.neighborhood,
      city:          simple['CIUDAD']    || null,
      county:        simple['MUNICIPIO'] || simple['CIUDAD'] || null,
      state:         simple['ESTADO']    || null,
      zip_code:      simple['CP']        || dir.zip_code
    };
  }

  var origenFinal = nullAddress();
  if (esTraslado && tieneOrigen) origenFinal = origen;

  var equipoNums = Object.keys(equipos).map(function(k) { return parseInt(k); }).sort();
  var equipoArray = [];

  if (equipoNums.length > 0) {
    for (var ei = 0; ei < equipoNums.length; ei++) {
      var eq = equipos[equipoNums[ei]];
      equipoArray.push({
        serialNumber: eq.serialNumber || null,
        inv_status:   resolveStatus(eq.inv_status) || 'DISPONIBLE',
        inv_type:     eq.inv_type    || simple['FORMATO'] || 'CAJERO',
        inv_subtype:  eq.inv_subtype || null,
        inv_brand:    eq.inv_brand   || simple['MARCA']   || null,
        inv_model:    eq.inv_model   || simple['MODELO']  || null,
        id_externo:   eq.id_externo  || null,
        ext_carga:    eq.ext_carga   || simple['MONTA']   || null,
        ext_nombre:   eq.ext_nombre  || null,
        comments:     eq.comments    || null
      });
    }
  } else {
    equipoArray.push({
      serialNumber: simple['SERIE']      || null,
      inv_status:   resolveStatus(simple['BASE']) || 'DISPONIBLE',
      inv_type:     simple['FORMATO']    || 'CAJERO',
      inv_subtype:  null,
      inv_brand:    simple['MARCA']      || null,
      inv_model:    simple['MODELO']     || null,
      id_externo:   simple['ID_EXTERNO'] || null,
      ext_carga:    simple['MONTA']      || null,
      ext_nombre:   simple['NOMBRE']     || null,
      comments:     simple['ACTIVIDAD_TEXT'] || so_type_id
    });
  }

  var requirementsArray = [];
  var premisaNums = Object.keys(premisas).map(function(k) { return parseInt(k); }).sort();

  if (premisaNums.length > 0) {
    for (var pi = 0; pi < premisaNums.length; pi++) {
      var p = premisas[premisaNums[pi]];
      if (p.requirement) {
        requirementsArray.push({ requirement: p.requirement, comment: p.comment || null });
      }
    }
  }

  if (requirementsArray.length === 0) {
    requirementsArray.push({
      requirement: so_type_id,
      comment: [
        simple['BASE']  ? 'BASE: '  + simple['BASE']  : null,
        simple['NIVEL'] ? 'NIVEL: ' + simple['NIVEL'] : null,
        simple['MONTA'] ? 'MONTA: ' + simple['MONTA'] : null
      ].filter(Boolean).join('; ') || null
    });
  }

  var validation_errors = [];
  var fecha = simple['FECHA'] || '';
  if (!simple['EMAIL'])      validation_errors.push('implantador.email requerido');
  if (!cleanDate(fecha))     validation_errors.push('so_requested_date invalida: ' + fecha);
  if (!so_type_id)           validation_errors.push('so_type_id no identificado');
  var sinSerie = equipoArray.every(function(e) { return !e.serialNumber; });
  if (sinSerie)              validation_errors.push('equipment: al menos un equipo requiere serialNumber');

  results.push({
    json: {
      service_order: {
        customer_id:       resolveCustomer(simple['ID'], simple['CLIENTE']),
        so_type_id:        so_type_id,
        so_service_id:     simple['SERVICIO'] || null,
        so_customer_folio: simple['FOLIO']    || simple['ID'] || null,
        so_requested_date: cleanDate(fecha),
        so_requested_time: cleanTime(simple['HORA'])
      },
      implantador: {
        email:           simple['EMAIL']        || null,
        phone:           simple['TELEFONO']     || null,
        firstname:       simple['NOMBRE_IMP']   || null,
        midname:         simple['MIDNAME']      || null,
        lastname:        simple['APELLIDO']     || null,
        mother_lastname: simple['APELLIDO_MAT'] || null
      },
